56	        alt: 'Natura Mini Dress, Ivory',
57	      },
58	      currentPrice: 'AUD 895.00',
59	    });
60	  });
61	
62	  test('id and href are built from the product id', () => {
63	    const card = selectRecentlyViewedCard(FULL, formatPrice);
64	    expect(card?.id).toBe('REC-PRODUCT-ID-0001');
65	  });
66	
