85	    expect(selectRecentlyViewedCard({ ...FULL, name: undefined }, formatPrice)).toBeNull();
86	  });
87	
88	  test('returns null when name is an empty string', () => {
89	    expect(selectRecentlyViewedCard({ ...FULL, name: '' }, formatPrice)).toBeNull();
90	  });
91	
92	  test('returns null for a nullish product (still loading)', () => {
93	    expect(selectRecentlyViewedCard(undefined, formatPrice)).toBeNull();
94	    expect(selectRecentlyViewedCard(null, formatPrice)).toBeNull();
95	  });
96	});
97	
98	describe('selectRecentlyViewedCard — no usable image, no card', () => {
99	  // Decision (documented, not silently made): "no usable image at all" is treated the same as
100	  // "no usable name" — a hard null gate — rather than a placeholder-image card. A placeholder
101	  // would need an asset/src this codebase has no confirmed token for, and null is the only
102	  // choice that structurally cannot violate ZimmProductCardMediaImage.alt's required-non-empty
103	  // contract (there is no returned object for alt to be empty on). See selectPrimaryImage's own
104	  // docblock in recentlyViewedCard.ts for the same note at the point of the decision.
105	  test('returns null when imageGroups is absent entirely (no flat-image fallback exists any more)', () => {
106	    expect(selectRecentlyViewedCard({ ...FULL, imageGroups: undefined }, formatPrice)).toBeNull();
107	  });
108	
109	  test('returns null when imageGroups is an empty array', () => {
110	    expect(selectRecentlyViewedCard({ ...FULL, imageGroups: [] }, formatPrice)).toBeNull();
111	  });
112	
113	  test('returns null when imageGroups filtering matches nothing (no medium viewType)', () => {
114	    const noMediumGroup: RecentlyViewedProduct = {
115	      ...FULL,
116	      imageGroups: [{ viewType: 'large', images: [{ link: 'https://example.test/large-only.jpg' }] }],
117	    };
118	    expect(selectRecentlyViewedCard(noMediumGroup, formatPrice)).toBeNull();
119	  });
120	
121	  test('returns null when the medium group has no images at all', () => {
122	    const emptyMediumGroup: RecentlyViewedProduct = {
123	      ...FULL,
124	      imageGroups: [{ viewType: 'medium', images: [] }],
125	    };
126	    expect(selectRecentlyViewedCard(emptyMediumGroup, formatPrice)).toBeNull();
127	  });
