66	// when pulled in transitively — same known gap use-toast.js has everywhere else it's imported in
67	// this codebase's own tests (see recommended-products/index.test.tsx's identical mock).
68	vi.mock('@salesforce/retail-react-app/app/hooks/use-toast', () => ({
69	  useToast: () => vi.fn(),
