97	// Two products, deliberately different `id`s, so a mapping/filtering bug (wrong product picked,
98	// or the null-filter dropping the wrong entry) fails loudly rather than coincidentally matching —
99	// same "G1" doctrine recentlyViewedCard.test.ts/recentlyViewedFullHistoryCard.test.ts document.
100	const mockProducts: RecentlyViewedFullHistoryProduct[] = [
101	  { id: 'rv-1', name: 'Product One' } as RecentlyViewedFullHistoryProduct,
102	  { id: 'rv-2', name: 'Product Two' } as RecentlyViewedFullHistoryProduct,
