349	      buildCard(product?.id ?? '', product?.name ?? ''),
350	    );
351	    mockResolveOrderableVariant.mockImplementation((product, sizeValue) =>
352	      product.id === 'rv-1' && sizeValue === 'xs' ? { productId: 'rv-1-XS', price: 300, orderable: true } : null,
353	    );
354	
355	    renderPage(true, addItemToNewOrExistingBasket);
