/**
 * SFCC-84 build plan step E2 — asserts only this container's own contract
 * (`.claude/rules/testing.md`'s no-duplicate-coverage rule): given `useEinstein()`'s own
 * `isLoading`/`recommendations`, does it render `ZimmRecentlyViewedGrid` (with the right computed
 * `title`/`itemCountLabel`/`cards`), this page's own empty state (correctly branched on
 * `isRegistered`), or neither — and does the item-count label actually pluralize via real ICU
 * `plural` resolution. `selectRecentlyViewedFullHistoryCard`, `resolveOrderableVariant`, and
 * `ZimmRecentlyViewedGrid` are all mocked at the smallest surface — their own internals already
 * have their own coverage elsewhere (`recentlyViewedFullHistoryCard.test.ts`,
 * `zimmRecentlyViewedGrid/index.test.tsx`).
 *
 * **Rewritten for build plan step E2** — the interim mechanism's own view-history-hook and
 * product-fetch-utility mocks are gone (both real modules deleted in build plan step E4; see
 * index.tsx's own module docblock, which names them directly). Every test case below now drives
 * its scenario entirely through `mockUseEinstein`, matching the exact pattern build plan step E1
 * already established (`recommended-products/index.test.tsx`). Product fixtures keep the same
 * `RecentlyViewedFullHistoryProduct` shape as before — a hydrated Einstein rec is a strict
 * superset of it (see index.tsx's own module docblock) — only the mock supplying them changed.
 *
 * `useMultiSite` is mocked the same way `footer/index.test.tsx` already does for the same reason:
 * the empty state's CTAs use the base SFCC `Link` (`@salesforce/retail-react-app/app/components/
 * link`), which calls `useMultiSite().buildUrl` internally to site-prefix `href`. A real
 * `MemoryRouter` is still required underneath it (that `Link` renders a real `react-router-dom`
 * `Link`), matching `footer/index.test.tsx`'s own `renderContainer` wrapper.
 *
 * The item-count pluralization tests deliberately do NOT mock `react-intl` — an `IntlProvider`
 * with an empty `messages` map (matching `recommended-products/index.test.tsx`'s own
 * `<IntlProvider locale="en-AU" messages={{}}>`) falls back to each message's own
 * `defaultMessage`, so `formatMessage`'s real ICU `plural` resolution runs for real. Mocking
 * `formatMessage` itself would defeat the point of this specific test.
 */
import React from 'react';
import { describe, test, expect, vi, afterEach } from 'vitest';
import { render, screen, act } from '@testing-library/react';
import { IntlProvider } from 'react-intl';
import { MemoryRouter } from 'react-router-dom';
import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
import { useCustomerType, useShopperBasketsMutationHelper } from '@salesforce/commerce-sdk-react';
import useEinstein from '@salesforce/retail-react-app/app/hooks/use-einstein';
import { EINSTEIN_RECOMMENDERS } from '@salesforce/retail-react-app/app/constants';
import {
  selectRecentlyViewedFullHistoryCard,
  resolveOrderableVariant,
} from '../../utils/recentlyViewedFullHistoryCard';
import type { RecentlyViewedFullHistoryProduct } from '../../utils/recentlyViewedFullHistoryCard';
import { ZimmRecentlyViewedGrid } from '../../components/ui-kits/organisms/zimmRecentlyViewedGrid';
import type { ZimmProductCardProps } from '../../components/ui-kits/organisms/zimmProductCard';
import RecentlyViewed from '.';

// Every card this file's own buildCard() builds is `variation: 'plp'` -- narrows the rendered
// `ZimmProductCardProps` union so onAddToBag/selectedSizeChipValue/onSizeChipSelect (all `plp`-only
// fields) are accessible, matching product-list/index.tsx's own `ProductListCardProps`
// `Extract<ZimmProductCardProps, { variation: 'plp' }>` pattern.
const asPlpCard = (card: ZimmProductCardProps) => card as Extract<ZimmProductCardProps, { variation: 'plp' }>;

vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
  default: vi.fn(),
}));

vi.mock('@salesforce/commerce-sdk-react', () => ({
  useCustomerType: vi.fn(),
  useShopperBasketsMutationHelper: vi.fn(),
}));

// Real use-toast.js ships JSX in a .js-extension file that Vitest's default transform can't parse
// when pulled in transitively — same known gap use-toast.js has everywhere else it's imported in
// this codebase's own tests (see recommended-products/index.test.tsx's identical mock).
vi.mock('@salesforce/retail-react-app/app/hooks/use-toast', () => ({
  useToast: () => vi.fn(),
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-einstein', () => ({
  default: vi.fn(),
}));

vi.mock('../../utils/recentlyViewedFullHistoryCard', () => ({
  selectRecentlyViewedFullHistoryCard: vi.fn(),
  resolveOrderableVariant: vi.fn(),
}));

// Relative path, matching index.tsx's own import — overrideStyling.md's "Importing an
// already-overridden component" doctrine (irrelevant here in the base-path sense, since this
// organism has no base-SFCC equivalent at all, but the relative specifier must still match
// exactly for the mock to intercept the real import).
vi.mock('../../components/ui-kits/organisms/zimmRecentlyViewedGrid', () => ({
  ZimmRecentlyViewedGrid: vi.fn(() => <div data-testid="zimm-recently-viewed-grid-stub" />),
}));

const mockUseMultiSite = vi.mocked(useMultiSite);
const mockUseCustomerType = vi.mocked(useCustomerType);
const mockUseShopperBasketsMutationHelper = vi.mocked(useShopperBasketsMutationHelper);
const mockUseEinstein = vi.mocked(useEinstein);
const mockSelectRecentlyViewedFullHistoryCard = vi.mocked(selectRecentlyViewedFullHistoryCard);
const mockResolveOrderableVariant = vi.mocked(resolveOrderableVariant);
const mockZimmRecentlyViewedGrid = vi.mocked(ZimmRecentlyViewedGrid);

// Two products, deliberately different `id`s, so a mapping/filtering bug (wrong product picked,
// or the null-filter dropping the wrong entry) fails loudly rather than coincidentally matching —
// same "G1" doctrine recentlyViewedCard.test.ts/recentlyViewedFullHistoryCard.test.ts document.
const mockProducts: RecentlyViewedFullHistoryProduct[] = [
  { id: 'rv-1', name: 'Product One' } as RecentlyViewedFullHistoryProduct,
  { id: 'rv-2', name: 'Product Two' } as RecentlyViewedFullHistoryProduct,
];

/**
 * The exact `useEinstein()` return shape this container reads (`isLoading`,
 * `recommendations.recs`, `getRecommendations`) — matching the pattern
 * `recommended-products/index.test.tsx` (build plan step E1) already established for the same
 * hook. No `as never` cast needed here (unlike the other mocks above): `useEinstein` is a base
 * SFCC hook with no real TypeScript types of its own (covered by `vendor.d.ts`'s wildcard
 * `any`-typed module declaration), so `mockReturnValue` imposes no shape constraint — confirmed
 * against E1's own committed test file, which passes a plain object literal the same way.
 */
const mockEinsteinReturn = (
  isLoading: boolean,
  recs: RecentlyViewedFullHistoryProduct[],
  getRecommendations: (...args: unknown[]) => unknown = vi.fn(),
) => {
  mockUseEinstein.mockReturnValue({ isLoading, recommendations: { recs }, getRecommendations });
};

const renderPage = (
  isRegistered: boolean,
  addItemToNewOrExistingBasket: (...args: never[]) => Promise<unknown> = vi.fn().mockResolvedValue(undefined),
) => {
  mockUseMultiSite.mockReturnValue({ buildUrl: (path: string) => path } as never);
  mockUseCustomerType.mockReturnValue({ isRegistered } as never);
  mockUseShopperBasketsMutationHelper.mockReturnValue({ addItemToNewOrExistingBasket } as never);

  return render(
    <MemoryRouter>
      <IntlProvider locale="en-AU" messages={{}}>
        <RecentlyViewed />
      </IntlProvider>
    </MemoryRouter>,
  );
};

afterEach(() => {
  vi.clearAllMocks();
});

describe('RecentlyViewed — cards render when Einstein has recs', () => {
  test('renders ZimmRecentlyViewedGrid, not the empty state, when recs has items, and fires getRecommendations once on mount', () => {
    const mockGetRecommendations = vi.fn();
    mockEinsteinReturn(false, mockProducts, mockGetRecommendations);
    // rv-2 deliberately maps to `null` (e.g. no usable image/name) — proves this container's own
    // `.filter()` drops it instead of forwarding a null card or crashing.
    mockSelectRecentlyViewedFullHistoryCard.mockImplementation((product) =>
      product?.id === 'rv-2'
        ? null
        : {
            id: product?.id ?? '',
            href: `/product/${product?.id ?? ''}`,
            name: product?.name ?? '',
            headingLevel: 'h3',
            primaryImage: { src: 'https://example.test/image.jpg', alt: product?.name ?? '' },
            variation: 'plp',
          },
    );

    renderPage(true);

    expect(screen.getByTestId('zimm-recently-viewed-grid-stub')).toBeInTheDocument();
    expect(screen.queryByTestId('recently-viewed-empty')).not.toBeInTheDocument();

    // Build plan step E2: this container fires getRecommendations once on mount, for this one
    // recommender, with no seed products — matches recommended-products/index.tsx's own RV branch
    // (build plan step E1; open question 3: Einstein derives from cookieId/userId, not seed
    // products, for this recommender).
    expect(mockGetRecommendations).toHaveBeenCalledWith(EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED);

    expect(mockZimmRecentlyViewedGrid).toHaveBeenCalledTimes(1);
    const gridProps = mockZimmRecentlyViewedGrid.mock.calls[0][0];
    expect(gridProps.title).toBe('Recently Viewed');
    expect(gridProps.cards).toHaveLength(1);
    expect(gridProps.cards[0]).toMatchObject({ id: 'rv-1', variation: 'plp' });
  });
});

describe('RecentlyViewed — page heading (2026-09-10 fix: this page had no Heading element at all)', () => {
  test('renders a real h1 with the page title, in the populated branch', () => {
    mockEinsteinReturn(false, mockProducts);
    // A real mapped card for every product (not `null`) -- this scenario must actually land on the
    // grid branch to match its own "populated branch" label. Before the 2026-09-15 gate fix (see
    // the "all-stale-history gate" test below), this fixture's own `null` return meant `cards`
    // was empty regardless, which no longer takes the grid branch now that the gate reads
    // `cards.length` instead of `recs.length` -- corrected here so this test still exercises what
    // its name says it does.
    mockSelectRecentlyViewedFullHistoryCard.mockImplementation((product) => ({
      id: product?.id ?? '',
      href: `/product/${product?.id ?? ''}`,
      name: product?.name ?? '',
      headingLevel: 'h3',
      primaryImage: { src: 'https://example.test/image.jpg', alt: product?.name ?? '' },
      variation: 'plp',
    }));

    renderPage(true);

    expect(screen.getByRole('heading', { level: 1, name: 'Recently Viewed' })).toBeInTheDocument();
    expect(screen.getByTestId('zimm-recently-viewed-grid-stub')).toBeInTheDocument();
  });

  test('renders a real h1 with the page title, in the empty branch', () => {
    mockEinsteinReturn(false, []);

    renderPage(true);

    expect(screen.getByRole('heading', { level: 1, name: 'Recently Viewed' })).toBeInTheDocument();
  });
});

describe('RecentlyViewed — empty state, branched on isRegistered', () => {
  test('registered: shows the registered body copy and only the Continue Shopping CTA', () => {
    mockEinsteinReturn(false, []);

    renderPage(true);

    expect(screen.getByTestId('recently-viewed-empty')).toBeInTheDocument();
    expect(screen.queryByTestId('zimm-recently-viewed-grid-stub')).not.toBeInTheDocument();
    expect(screen.getByText("You haven't viewed anything yet.")).toBeInTheDocument();
    expect(screen.getByText('Continue shopping to start building your history.')).toBeInTheDocument();
    expect(screen.getByRole('link', { name: 'Continue Shopping' })).toBeInTheDocument();
    expect(screen.queryByRole('link', { name: 'Sign In' })).not.toBeInTheDocument();
    expect(mockSelectRecentlyViewedFullHistoryCard).not.toHaveBeenCalled();
  });

  test('guest: shows the guest body copy and both Continue Shopping and Sign In CTAs', () => {
    mockEinsteinReturn(false, []);

    renderPage(false);

    expect(screen.getByTestId('recently-viewed-empty')).toBeInTheDocument();
    expect(screen.getByText('Sign in to keep track of your history, or continue shopping.')).toBeInTheDocument();
    const continueShoppingLink = screen.getByRole('link', { name: 'Continue Shopping' });
    const signInLink = screen.getByRole('link', { name: 'Sign In' });
    expect(continueShoppingLink).toHaveAttribute('href', '/');
    expect(signInLink).toHaveAttribute('href', '/account');
  });

  test('race-safe gate (build plan step E2, decision #3): does not render the empty state while isLoading is true, even with zero recs resolved so far', () => {
    // This is the exact race the race-safe gate exists to prevent: a genuine returning shopper's
    // getRecommendations request is still in flight (isLoading true) and recs has not resolved yet
    // (still empty) — gating on `!isLoading && recs.length === 0` (rather than `recs.length === 0`
    // alone) is what stops "you haven't viewed anything yet" from flashing during that window.
    // Verified directly, not just asserted: temporarily removing the `!isLoading` half of that
    // condition in index.tsx (leaving only `recs.length === 0`) makes this exact test fail — the
    // empty-state testid renders — and restoring the real gate makes it pass again.
    mockEinsteinReturn(true, []);

    renderPage(true);

    expect(screen.queryByTestId('recently-viewed-empty')).not.toBeInTheDocument();
    expect(screen.queryByTestId('zimm-recently-viewed-grid-stub')).not.toBeInTheDocument();
    expect(mockSelectRecentlyViewedFullHistoryCard).not.toHaveBeenCalled();
  });

  test('all-stale-history gate (2026-09-15 fix, CodeRabbit finding, personally verified before treating as valid): renders the empty state, not a blank page, when recs has items but every one fails to map to a card', () => {
    // The exact bug this closes: with the old `recs.length`-based gate, a shopper with real (if
    // all-stale) history -- every returned rec now offline/deleted, so
    // `selectRecentlyViewedFullHistoryCard` returns `null` for every one of them -- saw
    // `recs.length > 0` (2 items) evaluate true and took the grid branch with `cards={[]}`, which
    // `ZimmRecentlyViewedGrid` renders as `null` per its own documented contract: a blank page with
    // no explanation, not this page's own empty state.
    //
    // Verified directly, not just asserted (this codebase's prove-don't-assert discipline):
    // temporarily reverting index.tsx's gate back to `recs.length > 0` /
    // `!isLoading && recs.length === 0` made this exact test fail -- `recently-viewed-empty` was
    // absent and `zimm-recently-viewed-grid-stub` was present instead -- and restoring the
    // `cards.length` gate made it pass again.
    mockEinsteinReturn(false, mockProducts);
    mockSelectRecentlyViewedFullHistoryCard.mockReturnValue(null);

    renderPage(true);

    expect(screen.getByTestId('recently-viewed-empty')).toBeInTheDocument();
    expect(screen.queryByTestId('zimm-recently-viewed-grid-stub')).not.toBeInTheDocument();
    expect(screen.getByText("You haven't viewed anything yet.")).toBeInTheDocument();
  });
});

describe('RecentlyViewed — item count pluralization (real ICU plural resolution)', () => {
  test('renders "1 item" (singular) for a single card', () => {
    mockEinsteinReturn(false, [mockProducts[0]]);
    mockSelectRecentlyViewedFullHistoryCard.mockReturnValue({
      id: 'rv-1',
      href: '/product/rv-1',
      name: 'Product One',
      headingLevel: 'h3',
      primaryImage: { src: 'https://example.test/image.jpg', alt: 'Product One' },
      variation: 'plp',
    });

    renderPage(true);

    const gridProps = mockZimmRecentlyViewedGrid.mock.calls[0][0];
    expect(gridProps.itemCountLabel).toBe('1 item');
  });

  test('renders "2 items" (plural) for two cards', () => {
    mockEinsteinReturn(false, mockProducts);
    mockSelectRecentlyViewedFullHistoryCard.mockImplementation((product) => ({
      id: product?.id ?? '',
      href: `/product/${product?.id ?? ''}`,
      name: product?.name ?? '',
      headingLevel: 'h3',
      primaryImage: { src: 'https://example.test/image.jpg', alt: product?.name ?? '' },
      variation: 'plp',
    }));

    renderPage(true);

    const gridProps = mockZimmRecentlyViewedGrid.mock.calls[0][0];
    expect(gridProps.itemCountLabel).toBe('2 items');
  });
});

describe('RecentlyViewed — size-aware Add to Bag (2026-09-09, full parity with product-list/index.tsx)', () => {
  const buildCard = (id: string, name: string) => ({
    id,
    href: `/product/${id}`,
    name,
    headingLevel: 'h3' as const,
    primaryImage: { src: 'https://example.test/image.jpg', alt: name },
    variation: 'plp' as const,
  });

  test("with no size selected, adds the product's own default id/price and never calls resolveOrderableVariant", () => {
    const addItemToNewOrExistingBasket = vi.fn().mockResolvedValue(undefined);
    mockEinsteinReturn(false, [{ ...mockProducts[0], price: 250 }]);
    mockSelectRecentlyViewedFullHistoryCard.mockReturnValue(buildCard('rv-1', 'Product One'));

    renderPage(true, addItemToNewOrExistingBasket);

    const gridProps = mockZimmRecentlyViewedGrid.mock.calls[0][0];
    act(() => {
      asPlpCard(gridProps.cards[0]).onAddToBag?.();
    });

    expect(mockResolveOrderableVariant).not.toHaveBeenCalled();
    expect(addItemToNewOrExistingBasket).toHaveBeenCalledWith([{ productId: 'rv-1', price: 250, quantity: 1 }]);
  });

  test('selecting a size chip then adding to bag resolves the real orderable variant for that card only', () => {
    const addItemToNewOrExistingBasket = vi.fn().mockResolvedValue(undefined);
    mockEinsteinReturn(false, mockProducts);
    mockSelectRecentlyViewedFullHistoryCard.mockImplementation((product) =>
      buildCard(product?.id ?? '', product?.name ?? ''),
    );
    mockResolveOrderableVariant.mockImplementation((product, sizeValue) =>
      product.id === 'rv-1' && sizeValue === 'xs' ? { productId: 'rv-1-XS', price: 300, orderable: true } : null,
    );

    renderPage(true, addItemToNewOrExistingBasket);

    // Selecting a size chip is a state update outside a real DOM event -- act() flushes it so the
    // next render's props (captured below, not the stale first-render snapshot) reflect it.
    act(() => {
      asPlpCard(mockZimmRecentlyViewedGrid.mock.calls[0][0].cards[0]).onSizeChipSelect?.('xs');
    });

    const latestCall = mockZimmRecentlyViewedGrid.mock.calls[mockZimmRecentlyViewedGrid.mock.calls.length - 1][0];
    // Only rv-1's card picked up the selection -- rv-2's own selectedSizeChipValue is untouched,
    // proving this is a per-card id-keyed map, not one shared piece of page-level state.
    expect(asPlpCard(latestCall.cards[0]).selectedSizeChipValue).toBe('xs');
    expect(asPlpCard(latestCall.cards[1]).selectedSizeChipValue).toBeUndefined();

    act(() => {
      asPlpCard(latestCall.cards[0]).onAddToBag?.();
    });

    expect(mockResolveOrderableVariant).toHaveBeenCalledWith(mockProducts[0], 'xs');
    expect(addItemToNewOrExistingBasket).toHaveBeenCalledWith([{ productId: 'rv-1-XS', price: 300, quantity: 1 }]);
  });

  test("a selection matching no real variant falls back to the product's own default id/price, same as no selection at all", () => {
    const addItemToNewOrExistingBasket = vi.fn().mockResolvedValue(undefined);
    mockEinsteinReturn(false, [{ ...mockProducts[0], price: 250 }]);
    mockSelectRecentlyViewedFullHistoryCard.mockReturnValue(buildCard('rv-1', 'Product One'));
    mockResolveOrderableVariant.mockReturnValue(null);

    renderPage(true, addItemToNewOrExistingBasket);

    act(() => {
      asPlpCard(mockZimmRecentlyViewedGrid.mock.calls[0][0].cards[0]).onSizeChipSelect?.('no-such-size');
    });
    const latestCall = mockZimmRecentlyViewedGrid.mock.calls[mockZimmRecentlyViewedGrid.mock.calls.length - 1][0];
    act(() => {
      asPlpCard(latestCall.cards[0]).onAddToBag?.();
    });

    expect(addItemToNewOrExistingBasket).toHaveBeenCalledWith([{ productId: 'rv-1', price: 250, quantity: 1 }]);
  });
});

import React from 'react';
import type { ReactNode } from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { Link as RouteLink } from 'react-router-dom';
import { useRecentlyViewedRailVisibleCount } from 'app/hooks/useRecentlyViewedRailVisibleCount';
import { ZimmProductCard } from '../zimmProductCard';
import type { ZimmProductCardProps } from '../zimmProductCard';

// Same `chakra(RouteLink)` wrap this component family already establishes for its own internal
// links (zimmProductCard/index.tsx's `MediaOnlyCardLink`, zimmProductCardContent/index.tsx's
// `ProductNameLink`) — used here for the See-Full-History link, which navigates to the SFCC-84
// Recently Viewed Full History page, an internal route, not an external URL.
const SeeAllLink = chakra(RouteLink);

export type ZimmRecentlyViewedRailProps = {
  /**
   * Typed as `ReactNode`, not `string` — this component owns no copy/intl (the container, A6,
   * does). **Styling resolved 2026-09-08** (was previously left unstyled pending confirmation —
   * live Storybook testing caught the resulting bug: the title rendered in the ambient body
   * weight, Futura Round 400, instead of the design's intended weight): this component now
   * applies `textStyle="heading3"` itself when rendering `title`, matching the exact spec
   * confirmed against the Full History page's own title bar this same session (Figma
   * `Default/h3-strong` — Futura Round, 16px/18 line-height, weight 500, letter-spacing -0.12px,
   * uppercase — cross-checked against this codebase's registered `heading3` token, an exact
   * match). Applying it here rather than requiring every caller to pre-style the title guarantees
   * the design intent regardless of what a caller passes; a caller supplying an already fully
   * styled element can still override any of this via its own more-specific styling.
   */
  title: ReactNode;
  /**
   * Rendered in the exact order received (AC 2: most-recent-first, left to right) — no sorting or
   * reordering happens here. Capped to `RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS` for the current real
   * breakpoint regardless of length — a hard cap, not a "fits before scrolling" soft limit (see
   * that constant's own comment, app/constants/index.ts, and this component's own render-body
   * comment below for why the cap has to live here rather than in the request that produced this
   * array).
   */
  cards: readonly ZimmProductCardProps[];
  /** Href to the SFCC-84 Recently Viewed Full History page. The See-Full-History link only
   *  renders when this is provided — see the render body below. */
  seeAllHref?: string;
  /**
   * No default/fallback text is supplied when this is omitted while `seeAllHref` is provided —
   * this component owns no copy or intl (see the module docblock), so inventing an English
   * fallback here would risk shipping untranslated text on non-English storefronts. In real usage
   * the container (A6) is expected to always supply this alongside `seeAllHref`.
   */
  seeAllLabel?: string;
};

const ZIMM_RECENTLY_VIEWED_RAIL_RECIPE = 'ZimmRecentlyViewedRail';

/**
 * SFCC-83 — the Recently Viewed rail organism (build plan section A5). Purely presentational:
 * data arrives as props, no data-fetching, no `useEinstein`, no `useIntl` — see
 * .claude/rules/components.md's container/presentational split. The container (A6) is
 * responsible for building `cards` (via A3's Einstein-rec-to-card mapper), gating this
 * component's visibility (A4's `hasRecentlyViewed`), and supplying `title`/`seeAllLabel` copy.
 *
 * Structure mirrors Figma exactly: a `header` row (title left, the See-Full-History link right)
 * above a `group` of `ZimmProductCard`s. No rail-level arrow buttons — `ZimmProductCardMedia`
 * already carries its own intra-card carousel arrows, and a second set at the rail level would
 * collide with them (see zimmRecentlyViewedRail.css.ts's own docblock for the Figma node
 * evidence).
 *
 * **`group`'s horizontal scroll/scroll-snap (zimmRecentlyViewedRail.css.ts) is a narrow-viewport
 * safety net, not the "more cards exist, scroll to see them" mechanism it might look like.**
 * Confirmed with Marcel (2026-09-08): the per-breakpoint card count below is a hard cap — a
 * shopper on a real, design-reference-width device never has more cards to scroll to than the
 * cap allows; "more history exists" is surfaced via the See-Full-History link (the container's
 * own job), not via scrolling this rail further. The scroll/scroll-snap CSS stays
 * meaningful only for a real device narrower than the design reference itself (e.g. a phone
 * under ~402px), where the capped card count can still slightly overflow the actual viewport.
 *
 * `cards` is typed as the full `ZimmProductCardProps` union, matching this step's own given
 * component contract verbatim — this component therefore spreads each entry straight into
 * `ZimmProductCard` (`<ZimmProductCard {...card} />`) rather than forcing
 * `variation: 'recentlyViewed'` onto every card itself. In real usage every entry already carries
 * that variation by construction (A3's mapper produces `recentlyViewed`-shaped cards, matching
 * `variation: 'recentlyViewed'` in the type union — see zimmProductCard/index.tsx's
 * `ZimmProductCardRecentlyViewedVariation`) — this component trusts that contract rather than
 * re-asserting it, consistent with staying purely presentational.
 *
 * `data-testid="product-card"` / `data-product-id` on each rendered card come from
 * `ZimmProductCard`'s own root (zimmProductCard/index.tsx: "a DOM hook for QA automation/
 * analytics") — this component adds no additional per-card test hook of its own.
 */
export const ZimmRecentlyViewedRail = ({ title, cards, seeAllHref, seeAllLabel }: ZimmRecentlyViewedRailProps) => {
  const styles = useMultiStyleConfig(ZIMM_RECENTLY_VIEWED_RAIL_RECIPE, {});

  // Cap is enforced here, client-side, regardless of how many cards were passed in — the data
  // source (Einstein's own `recommendations.recs`, wired in build plan step E1) does not itself
  // honour a requested limit, and per-breakpoint capping is this component's own presentational
  // concern, not the container's. Falls back to the smallest (base/mobile) count on the very first render
  // before the client-side media-query match resolves (see RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS's
  // own comment, app/constants/index.ts, for why this is a hard per-breakpoint cap, not a "fits
  // before scrolling" soft limit). A slice, never a sort — order is otherwise untouched (AC 2).
  //
  // `useRecentlyViewedRailVisibleCount()`, not a direct `useBreakpointValue` call (corrected
  // 2026-09-10 — see that hook's own docblock for the live-confirmed bug this closes): this
  // component's own Desktop card-width styling (zimmRecentlyViewedRail.css.ts's
  // `DESKTOP_UP_QUERY`) switches at 1024px, not this site's shared `breakpoints.xl` (1280px) that
  // `useBreakpointValue` would have resolved against — the two disagreeing meant a real, narrow
  // window (1024–1280px) where cards were already styled for 5 slots but only 3 were allowed to
  // render.
  const maxVisibleCards = useRecentlyViewedRailVisibleCount();
  const visibleCards = cards.slice(0, maxVisibleCards);

  // Second guard behind A4's own visibility gate, which lives in the container, not here — an
  // empty rail renders nothing at all, not an empty shell.
  if (visibleCards.length === 0) {
    return null;
  }

  return (
    <chakra.div __css={styles.container} data-testid="recently-viewed-rail">
      <chakra.div __css={styles.header}>
        {/* flex/minWidth match Figma's own title node (flex: 1 0 0, min-w-px) — grows to fill
            whatever `header`'s own gap + the link's width don't claim, and can shrink below its
            own text's intrinsic width rather than force an overflow. See zimmRecentlyViewedRail.css.ts's
            own "TITLE/LINK SPACING" docblock section. */}
        <chakra.span textStyle="heading3" flex="1 0 0" minWidth={0}>
          {title}
        </chakra.span>
        {seeAllHref && seeAllLabel && (
          <SeeAllLink to={seeAllHref} textStyle="linkLg" __css={styles.seeAllLink}>
            {seeAllLabel}
          </SeeAllLink>
        )}
      </chakra.div>
      <chakra.div __css={styles.group} data-testid="recently-viewed-rail-group">
        {visibleCards.map((card) => (
          <chakra.div key={card.id} __css={styles.card}>
            <ZimmProductCard {...card} />
          </chakra.div>
        ))}
      </chakra.div>
    </chakra.div>
  );
};

