1	/**
2	 * Scoped per .claude/rules/testing.md: this component's OWN contract only — cap enforcement,
3	 * order preservation, empty-input renders null, and the See-Full-History link's presence gated
4	 * on `seeAllHref`. `ZimmProductCard`'s own internals (badge rendering, hover-swap, accessible-name
5	 * concatenation, etc.) are already covered by zimmProductCard/index.test.tsx and are deliberately
6	 * NOT re-tested here — testing.md's "no duplicate coverage across layers".
7	 *
8	 * `ZimmProductCard` is composed for real here (not mocked out) — same "costs nothing, gives real
9	 * integration confidence" precedent zimmProductCard/index.test.tsx and
10	 * zimmProductCardContent/index.test.tsx already document for their own composed children. Its own
11	 * `data-testid="product-card"` / `data-product-id` DOM hooks (zimmProductCard/index.tsx's own
12	 * docblock: "a DOM hook for QA automation/analytics") are what this file's cap/order assertions
13	 * read — a stable, intentional surface, not an internal implementation detail being reached into.
14	 *
15	 * `useMultiStyleConfig` is mocked with one flat object covering every part every composed
16	 * descendant reads (this component's own 5 parts, plus ZimmProductCard's `root` and
17	 * ZimmProductCardMedia's 12 parts) — same "neither test setup nor Chakra cares which recipe name
18	 * asked for it" precedent zimmProductCard/index.test.tsx and zimmProductCardMedia/index.test.tsx
19	 * document. `ZimmProductCardContent` never mounts for the `recentlyViewed` variation
20	 * (`VARIATION_CONFIG.showContent` is false there), so its own parts are not needed here.
21	 *
22	 * The icon-module mocks below are the same known Vitest SVG-import issue documented in
23	 * .claude/rules/testing.md ("Known gap: ZimmIcon throws under Vitest") and already mocked in
24	 * zimmProductCard/index.test.tsx — copied verbatim since this file sits at the identical
25	 * ui-kits/organisms/<name>/ depth, so the same relative specifiers resolve to the same modules.
26	 *
27	 * No `react-router-dom` mock (unlike zimmProductCard/index.test.tsx's own `useHistory` spy) —
28	 * this component never calls `useHistory` itself, and `ZimmProductCard`'s own click-passthrough
29	 * mechanism is already covered by that file's own tests, not re-proven here.
30	 */
31	import React from 'react';
32	import { describe, test, expect, vi, beforeEach } from 'vitest';
33	import { render, screen } from '@testing-library/react';
