1	import type { ShopperSearchTypes } from 'commerce-sdk-isomorphic';
2	import { getPriceData, filterImageGroups } from '@salesforce/retail-react-app/app/utils/product-utils';
3	import { productUrlBuilder } from '@salesforce/retail-react-app/app/utils/url';
4	import type {
5	  ZimmProductCardBaseProps,
6	  ZimmProductCardPlpVariation,
7	  ZimmProductCardImage,
8	} from '../../components/ui-kits/organisms/zimmProductCard';
9	import type { ZimmSizeChipValue } from '../../components/ui-kits/molecules/zimmSizeChipGroup';
10	import { sortImagesBySequence, resolveFallbackColour, toGalleryAlt } from '../../utils/productCardMappingHelpers';
11	
12	// This mapper is PLP-only by design, so it returns the narrowed shape directly rather than the
13	// full `ZimmProductCardProps` union — letting a caller pass the result straight to a
14	// PLP-typed component (like this page's own `ProductListCard`) with no re-narrowing needed.
15	type ProductListCardResult = ZimmProductCardBaseProps & ZimmProductCardPlpVariation;
16	
17	/**
18	 * `c_productBadges` is a custom SFCC attribute (SFCC-225's own already-merged SCAPI hook) with no
19	 * typed field on the base SDK's `ProductSearchHit` — it only reaches this shape via that type's
20	 * own `{[key: string]: any}` index signature. Narrowed here to the one shape this mapper reads,
21	 * rather than trusting `any` at every call site.
22	 */
23	export type ProductListSearchHit = ShopperSearchTypes.ProductSearchHit & {
24	  c_productBadges?: Array<{ productBadge?: string }>;
25	};
26	
27	type RawImage = { alt?: string; disBaseLink?: string; link?: string };
28	
29	const toCardImage = (image: RawImage | undefined): ZimmProductCardImage | undefined => {
30	  const src = image?.disBaseLink ?? image?.link;
31	  if (!src) return undefined;
32	  return { src, alt: toGalleryAlt(image?.alt) };
33	};
34	
35	/** The correctly-sized product image view — never serve an arbitrary-sized image at thumbnail
36	 *  size (AGENTS.md's image-sizing guidance). Same constant, same reasoning, as
37	 *  `recentlyViewedFullHistoryCard.ts`'s own `MEDIUM_VIEW_TYPE`. */
38	const MEDIUM_VIEW_TYPE = 'medium';
39	
40	/** The variation-attribute id `filterImageGroups` matches an image group's colour against —
41	 *  named per conventions.md's no-magic-strings rule. */
42	const COLOUR_VARIATION_ATTRIBUTE_ID = 'color';
43	
44	/** The one shape this mapper reads off a `filterImageGroups` result — that function ships from
45	 *  an untyped base-SFCC module (`@salesforce/retail-react-app` has no types for this subpath, see
46	 *  `RawImage`'s own comment above for the same reasoning), so this documents an assumed shape
47	 *  rather than letting `any` propagate silently. */
48	type ImageGroupShape = { images?: RawImage[] };
49	
