test('id and href are built from the product id', () => {
  const card = selectRecentlyViewedCard(FULL, formatPrice, buildUrl);
  expect(card?.id).toBe('REC-PRODUCT-ID-0001');
});

test('href is productUrlBuilder\'s bare /product/{id} path when buildUrl is the identity fixture', () => {
  const card = selectRecentlyViewedCard(FULL, formatPrice, buildUrl);
  expect(card?.href).toBe('/product/REC-PRODUCT-ID-0001');
  expect(card?.href).not.toMatch(/^https?:\/\//);
});

// Fixed 2026-09-15 (CodeRabbit finding, confirmed): this mapper used to build `href` from
// `productUrlBuilder` alone, with no site/locale prefix at all — on a non-default storefront,
// every Recently Viewed card silently linked back to the default site/locale instead of the one
// actually being browsed. `buildUrl` is now applied to that bare path (see
// recentlyViewedCard.ts's own docblock) — proven here with a fixture that prepends a
// distinguishing, unmistakable prefix, not the identity fixture every other test in this file
// uses (which would pass even if `buildUrl` were silently ignored).
test('applies buildUrl to productUrlBuilder\'s output, not just the caller-supplied identity fixture', () => {
  const prefixingBuildUrl = (path: string) => `/en-GB${path}`;
  const card = selectRecentlyViewedCard(FULL, formatPrice, prefixingBuildUrl);
  expect(card?.href).toBe('/en-GB/product/REC-PRODUCT-ID-0001');

